#include <config.h>

#include "idn2.h"

#include <errno.h>              /* errno */
#include <stdlib.h>             /* malloc, free */

#include "punycode.h"

#include <unitypes.h>
#include <uniconv.h>            /* u8_strconv_from_locale */
