          else if (map_is (&map, TR46_FLG_DISALLOWED_STD3_MAPPED))
            {
              /* mapped because UseSTD3ASCIIRules=false, see #TR46 5 */
              len2 += map.nmappings;
            }
        }
    }

  /* Exit early if result is too long.
   * This avoids excessive CPU usage in punycode encoding, which is O(N^2). */
